public class TaskRunner implements Runnable {
    private volatile boolean running = true;  // volatile ensures visibility
    private int taskCount = 0;

    @Override
    public void run() {
        while (running) {  // main thread can stop this loop
            processTask();
            taskCount++;  // NOT thread-safe even with volatile running!
        }
        System.out.println("Stopped after " + taskCount + " tasks");
    }

    private void processTask() {
        // simulate work
        try { Thread.sleep(100); } catch (InterruptedException e) {}
    }

    public void stop() {
        running = false;  // visible immediately to worker thread
    }
}
