public class DatabaseConnectionPool {
    private volatile static DatabaseConnectionPool instance;  // volatile is critical
    private final List<Connection> connections;

    private DatabaseConnectionPool() {
        // expensive initialization
        connections = new ArrayList<>();
        for (int i = 0; i < 10; i++) {
            connections.add(createConnection());
        }
    }

    public static DatabaseConnectionPool getInstance() {
        if (instance == null) {  // first check without locking
            synchronized (DatabaseConnectionPool.class) {
                if (instance == null) {  // second check with lock
                    instance = new DatabaseConnectionPool();  // volatile write
                }
            }
        }
        return instance;  // volatile read ensures fully constructed
    }

    private Connection createConnection() { return null; }
}
