public class ConfigLoader {
    private Map<String, String> config;  // not volatile
    private volatile boolean configReady = false;  // volatile flag

    // Thread A: Loader thread
    public void loadConfig() {
        var tempConfig = new HashMap<String, String>();
        tempConfig.put("db.url", "jdbc:postgresql://localhost/app");
        tempConfig.put("db.user", "admin");
        // all these writes happen-before the volatile write below
        config = tempConfig;
        configReady = true;  // volatile write establishes happens-before
    }

    // Thread B: Worker thread
    public String getConfigValue(String key) {
        if (configReady) {  // volatile read
            // guaranteed to see fully initialized config map
            return config.get(key);
        }
        return null;
    }
}
