public class RequestTracker {
    private volatile long lastRequestTimestamp;  // volatile ensures atomicity and visibility
    private final AtomicLong requestCount = new AtomicLong();

    public void recordRequest() {
        requestCount.incrementAndGet();
        lastRequestTimestamp = System.currentTimeMillis();  // atomic write of 64-bit value
    }

    public long getLastRequestTimestamp() {
        return lastRequestTimestamp;  // atomic read of 64-bit value
    }

    public RequestStats getStats() {
        // both reads see consistent values due to volatile
        return new RequestStats(
            requestCount.get(),
            lastRequestTimestamp
        );
    }
}

record RequestStats(long count, long lastTimestamp) {}
